// Кейс: .qa/tests/support/SUP-002.md (шаги 1–4) · план: .qa/e2e-app/specs/app.md (1.28)
// @data: РЕАЛЬНАЯ отправка обращения — запись в support_requests и письмо на почту поддержки. Только с BANCI_SUPPORT_SEND=1.
// Текст: «QA-AUTO <дата> — נא להתעלם». Удалить запись нельзя — отметить в context.md «Тестовые данные для чистки».
// Приход письма на почту поддержки автотест не видит — проверяет человек (SUP-002 шаг 5).
import { by, assert, skip } from '../../lib/appium.mjs';
import { openSupport, supportTopic, SUPPORT } from '../../lib/banci.mjs';

export const name = '«תמיכה» → тема «אחר» → текст «QA-AUTO <дата> — נא להתעלם» → «שליחה» → «הפנייה נשלחה» → снова «חשבון» #39b1c8 @iphone @app @data';

const FIELD = 'type == "XCUIElementTypeTextView" OR type == "XCUIElementTypeTextField"';
const ERRORS = ['משהו השתבש', 'שגיאה', 'לא הצלחנו', 'נכשל'];

export default async function (app) {
  if (process.env.BANCI_SUPPORT_SEND !== '1') skip('реальная отправка обращения — только с BANCI_SUPPORT_SEND=1 (@data, письмо уйдёт в поддержку)');
  const text = `QA-AUTO ${new Date().toISOString().slice(0, 10)} — נא להתעלם`;

  // 1. «חשבון» → «תמיכה» → тема «אחר».
  await openSupport(app);
  await (await supportTopic(app, 'אחר')).click();

  // 2. Текст обращения.
  const field = await app.scrollTo(FIELD, { max: 3, what: 'поле текста обращения' });
  await field.click();
  await field.type(text);
  await app.exec('mobile: hideKeyboard', { keys: ['סיום', 'Done', 'Return', 'return'] }).catch(() => {});
  const value = String((await (await app.waitFor(FIELD, { what: 'поле текста обращения' })).attr('value')) ?? '');
  assert(value.includes('QA-AUTO'), `в поле введён текст «${text}» (сейчас «${value}»)`);

  // 3. «שליחה» → «הפנייה נשלחה» (комментарий программиста), ошибок нет.
  await (await app.scrollTo(by.exact(SUPPORT.send), { max: 3, what: 'кнопка «שליחה»' })).click();
  await app.waitFor(by.contains(SUPPORT.sent), { timeout: 20000, what: 'сообщение «הפנייה נשלחה» после «שליחה»' });
  for (const e of ERRORS) assert(!(await app.exists(by.contains(e))), `после «שליחה» нет ошибки «${e}»`);

  // 4. Возврат в «חשבון»: формы нет, строка «תמיכה» в списке.
  await app.waitGone(by.contains(SUPPORT.subjectLabel, 'StaticText'), { timeout: 15000, what: 'форма «תמיכה» закрылась' });
  await app.scrollTo(by.exact(SUPPORT.row, 'StaticText'), { what: 'снова «חשבון» со строкой «תמיכה»' });
  console.log(`[#39b1c8] отправлено обращение «${text}» — проверить письмо на почте поддержки (SUP-002 шаг 5) и записать в «Тестовые данные для чистки»`);

  await app.restart();
}
